(window.__qhadithX=window.__qhadithX||{})[35]={"6":[{"c":"Al-Adab Al-Mufrad","r":"Book 54, Hadith 1265","u":"https://quranx.com/Hadith/Adab/English/Book-54/Hadith-1265","x":"Ibn 'Abbas said that the words of Allah in Luqman (35:6), \"There are people who trade in distracting tales\" mean \"singing and things like it.\"","ar":"حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، قَالَ‏:‏ حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللهِ، قَالَ‏:‏ أَخْبَرَنَا عَطَاءُ بْنُ السَّائِبِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، فِي قَوْلِهِ عَزَّ وَجَلَّ‏:‏ ‏{‏وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ‏}‏، قَالَ‏:‏ الْغِنَاءُ وَأَشْبَاهُهُ‏.‏","v":[]}],"18":[{"c":"Sahih Bukhari","r":"Hadith 1286","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1286","x":"Narrated `Abdullah bin 'Ubaidullah bin Abi Mulaika:\n\nOne of the daughters of `Uthman died at Mecca. We went to attend her funeral procession. Ibn `Umar and Ibn `Abbas were also present. I sat in between them (or said, I sat beside one of them. Then a man came and sat beside me.) `Abdullah bin `Umar said to `Amr bin `Uthman, \"Will you not prohibit crying as Allah's Messenger (ﷺ) has said, 'The dead person is tortured by the crying of his relatives.?\" Ibn `Abbas said, \"`Umar used to say so.\" Then he added narrating, \"I accompanied `Umar on a journey from Mecca till we reached Al-Baida. There he saw some travelers in the shade of a Samura (A kind of forest tree). He said (to me), \"Go and see who those travelers are.\" So I went and saw that one of them was Suhaib. I told this to `Umar who then asked me to call him. So I went back to Suhaib and said to him, \"Depart and follow the chief of the faithful believers.\" Later, when `Umar was stabbed, Suhaib came in weeping and saying, \"O my brother, O my friend!\" (on this `Umar said to him, \"O Suhaib! Are you weeping for me while the Prophet (ﷺ) said, \"The dead person is punished by some of the weeping of his relatives?\" Ibn `Abbas added, \"When `Umar died I told all this to Aisha and she said, 'May Allah be merciful to `Umar. By Allah, Allah's Messenger (ﷺ) did not say that a believer is punished by the weeping of his relatives. But he said, Allah increases the punishment of a non-believer because of the weeping of his relatives.\" Aisha further added, \"The Qur'an is sufficient for you (to clear up this point) as Allah has stated: 'No burdened soul will bear another's burden.' \" (35.18). Ibn `Abbas then said, \"Only Allah makes one laugh or cry.\" Ibn `Umar did not say anything after that.","ar":"حَدَّثَنَا عَبْدَانُ، حَدَّثَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، قَالَ أَخْبَرَنِي عَبْدُ اللَّهِ بْنُ عُبَيْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ، قَالَ تُوُفِّيَتِ ابْنَةٌ لِعُثْمَانَ ـ رضى الله عنه ـ بِمَكَّةَ وَجِئْنَا لِنَشْهَدَهَا، وَحَضَرَهَا ابْنُ عُمَرَ وَابْنُ عَبَّاسٍ ـ رضى الله عنهم ـ وَإِنِّي لَجَالِسٌ بَيْنَهُمَا ـ أَوْ قَالَ جَلَسْتُ إِلَى أَحَدِهِمَا‏.‏ ثُمَّ جَاءَ الآخَرُ، فَجَلَسَ إِلَى جَنْبِي فَقَالَ عَبْدُ اللَّهِ بْنُ عَمَرَ ـ رضى الله عنهما ـ لِعَمْرِو بْنِ عُثْمَانَ أَلاَ تَنْهَى عَنِ الْبُكَاءِ، فَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏\"‏‏.‏ فَقَالَ ابْنُ عَبَّاسٍ ـ رضى الله عنهما ـ قَدْ كَانَ عُمَرُ ـ رضى الله عنه ـ يَقُولُ بَعْضَ ذَلِكَ، ثُمَّ حَدَّثَ قَالَ صَدَرْتُ مَعَ عُمَرَ ـ رضى الله عنه ـ مِنْ مَكَّةَ حَتَّى إِذَا كُنَّا بِالْبَيْدَاءِ، إِذَا هُوَ بِرَكْبٍ تَحْتَ ظِلِّ سَمُرَةٍ فَقَالَ اذْهَبْ، فَانْظُرْ مَنْ هَؤُلاَءِ الرَّكْبُ قَالَ فَنَظَرْتُ فَإِذَا صُهَيْبٌ، فَأَخْبَرْتُهُ فَقَالَ ادْعُهُ لِي‏.‏ فَرَجَعْتُ إِلَى صُهَيْبٍ فَقُلْتُ ارْتَحِلْ فَالْحَقْ أَمِيرَ الْمُؤْمِنِينَ‏.‏ فَلَمَّا أُصِيبَ عُمَرُ دَخَلَ صُهَيْبٌ يَبْكِي يَقُولُ وَاأَخَاهُ، وَاصَاحِبَاهُ‏.‏ فَقَالَ عُمَرُ ـ رضى الله عنه ـ يَا صُهَيْبُ أَتَبْكِي عَلَىَّ وَقَدْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ الْمَيِّتَ يُعَذَّبُ بِبَعْضِ بُكَاءِ أَهْلِهِ عَلَيْهِ ‏\"‏‏.‏ قَالَ ابْنُ عَبَّاسٍ ـ رضى الله عنهما فَلَمَّا مَاتَ عُمَرُ ـ رضى الله عنه ـ ذَكَرْتُ ذَلِكَ لِعَائِشَةَ ـ رضى الله عنها ـ فَقَالَتْ رَحِمَ اللَّهُ عُمَرَ، وَاللَّهِ مَا حَدَّثَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِنَّ اللَّهَ لَيُعَذِّبُ الْمُؤْمِنَ بِبُكَاءِ أَهْلِهِ عَلَيْهِ‏.‏ وَلَكِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ إِنَّ اللَّهَ لَيَزِيدُ الْكَافِرَ عَذَابًا بِبُكَاءِ أَهْلِهِ عَلَيْهِ ‏\"‏‏.‏ وَقَالَتْ حَسْبُكُمُ الْقُرْآنُ ‏{‏وَلاَ تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى‏}‏‏.‏ قَالَ ابْنُ عَبَّاسٍ ـ رضى الله عنهما ـ عِنْدَ ذَلِكَ وَاللَّهُ هُوَ أَضْحَكَ وَأَبْكَى‏.‏ قَالَ ابْنُ أَبِي مُلَيْكَةَ وَاللَّهِ مَا قَالَ ابْنُ عُمَرَ ـ رضى الله عنهما ـ شَيْئًا‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 2, Book 6, Hadith 1594","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-2/Book-6/Hadith-1594","x":"It was narrated from Asid bin Abu Asid, from Musa bin Abu Musa Ash’ari, from his father that the Prophet (ﷺ) said:\n\n\"The deceased is punished for the weeping of the living. If they say: ‘O my strength, O he who clothed us, O my help, O my rock,’ and so on, he is rebuked and it is said: ‘Were you really like that? Were you really like that?’\" Asid said: \"I said: 'Subhan-Allah! Allah says: \"And no bearer of burdens shall another's burden (35:18).\" He said: \"Woe to you, I tell you that Abu Musa narrated to me from the Messenger of Allah (ﷺ), and you think that Abu Musa was telling lies about the Prophet (ﷺ)? Or do you think that I am telling lies about Abu Musa?\"","ar":"حَدَّثَنَا يَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ الدَّرَاوَرْدِيُّ، حَدَّثَنَا أَسِيدُ بْنُ أَبِي أَسِيدٍ، عَنْ مُوسَى بْنِ أَبِي مُوسَى الأَشْعَرِيِّ، عَنْ أَبِيهِ، ‏.‏ أَنَّ النَّبِيَّ ـ صلى الله عليه وسلم ـ قَالَ ‏\"‏ الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ الْحَىِّ إِذَا قَالُوا وَاعَضُدَاهْ وَاكَاسِيَاهْ ‏.‏ وَانَاصِرَاهْ وَاجَبَلاَهْ وَنَحْوَ هَذَا - يُتَعْتَعُ وَيُقَالُ أَنْتَ كَذَلِكَ أَنْتَ كَذَلِكَ ‏\"‏ ‏.‏ قَالَ أَسِيدٌ فَقُلْتُ سُبْحَانَ اللَّهِ إِنَّ اللَّهَ يَقُولُ ‏{وَلاَ تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى }‏ ‏.‏ قَالَ وَيْحَكَ أُحَدِّثُكَ أَنَّ أَبَا مُوسَى حَدَّثَنِي عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَتَرَى أَنَّ أَبَا مُوسَى كَذَبَ عَلَى النَّبِيِّ ـ صلى الله عليه وسلم ـ أَوْ تَرَى أَنِّي كَذَبْتُ عَلَى أَبِي مُوسَى؟","v":[]}],"22":[{"c":"Sahih Bukhari","r":"Hadith 3978","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3978","x":"Narrated Hisham's father:\n\nIt was mentioned before `Aisha that Ibn `Umar attributed the following statement to the Prophet (ﷺ) \"The dead person is punished in the grave because of the crying and lamentation Of his family.\" On that, `Aisha said, \"But Allah's Messenger (ﷺ) said, 'The dead person is punished for his crimes and sins while his family cry over him then.\" She added, \"And this is similar to the statement of Allah's Messenger (ﷺ) when he stood by the (edge of the) well which contained the corpses of the pagans killed at Badr, 'They hear what I say.' She added, \"But he said now they know very well what I used to tell them was the truth.\" `Aisha then recited: 'You cannot make the dead hear.' (30.52) and 'You cannot make those who are in their Graves, hear you.' (35.22) that is, when they had taken their places in the (Hell) Fire.","ar":"حَدَّثَنِي عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، قَالَ ذُكِرَ عِنْدَ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ ابْنَ عُمَرَ رَفَعَ إِلَى النَّبِيِّ صلى الله عليه وسلم ‏\"‏ إِنَّ الْمَيِّتَ يُعَذَّبُ فِي قَبْرِهِ بِبُكَاءِ أَهْلِهِ ‏\"‏‏.‏ فَقَالَتْ إِنَّمَا قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّهُ لَيُعَذَّبُ بِخَطِيئَتِهِ وَذَنْبِهِ، وَإِنَّ أَهْلَهُ لَيَبْكُونَ عَلَيْهِ الآنَ ‏\"‏‏.‏ قَالَتْ وَذَاكَ مِثْلُ قَوْلِهِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَامَ عَلَى الْقَلِيبِ وَفِيهِ قَتْلَى بَدْرٍ مِنَ الْمُشْرِكِينَ، فَقَالَ لَهُمْ مَا قَالَ إِنَّهُمْ لَيَسْمَعُونَ مَا أَقُولُ‏.‏ إِنَّمَا قَالَ ‏\"‏ إِنَّهُمُ الآنَ لَيَعْلَمُونَ أَنَّ مَا كُنْتُ أَقُولُ لَهُمْ حَقٌّ ‏\"‏‏.‏ ثُمَّ قَرَأَتْ ‏{‏إِنَّكَ لاَ تُسْمِعُ الْمَوْتَى‏}‏ ‏{‏وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ‏}‏ تَقُولُ حِينَ تَبَوَّءُوا مَقَاعِدَهُمْ مِنَ النَّارِ‏.‏","v":[]}],"32":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3225","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3225","x":"Narrated Abu Sa'eed Al-Khudri:\n\nfrom the Prophet (ﷺ), that he said about this Ayah: 'Then We gave the Book the as inheritance to such of Our worshipers whom We chose. Then of them are some who wrong themselves, and of them are some who follow a middle course, and of them are some who are, by Allah's Leave, foremost in good deeds (35:32). He said: \"All of these people are of the same rank, and all of them are in Paradise.\"","ar":"حَدَّثَنَا أَبُو مُوسَى، مُحَمَّدُ بْنُ الْمُثَنَّى وَمُحَمَّدُ بْنُ بَشَّارٍ قَالاَ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنِ الْوَلِيدِ بْنِ عَيْزَارٍ، أَنَّهُ سَمِعَ رَجُلاً، مِنْ ثَقِيفٍ يُحَدِّثُ عَنْ رَجُلٍ، مِنْ كِنَانَةَ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ قَالَ فِي هَذِهِ الآيَةِ ‏:‏ ‏(‏ثمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ مُقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ ‏)‏ قَالَ ‏\"‏ هَؤُلاَءِ كُلُّهُمْ بِمَنْزِلَةٍ وَاحِدَةٍ وَكُلُّهُمْ فِي الْجَنَّةِ ‏\"‏ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ هَذَا الْوَجْهِ ‏.‏","v":[]}],"41":[{"c":"Al-Adab Al-Mufrad","r":"Book 50, Hadith 1214","u":"https://quranx.com/Hadith/Adab/English/Book-50/Hadith-1214","x":"Jabir said:\n\n\"When a man enters his house or goes to bed, an angel and shaytan hasten to him. The angel says, 'Seal it with good!' The Shaytan says, 'Seal it with evil.' If he praises Allah and remembers Him, he chases the shaytan away and spends the night with him guarding him. When he wakes up, the angel and shaytan hasten to him and say the same thing. If he mentions Allah and says, 'Praise be to Allah, who keeps firm hold of the heavens and earth, preventing them from vanishing away. And if they vanished no one could then keep hold of them. Certainly He is Most Forbearing, Ever-Forgiving.' (35:41) Praise be to Allah who holds back the sky preventing it from falling on the earth, except by His permission. Allah is All-Compassionate to mankind, Most Merciful.' (22:63) If he dies, he dies a martyr, If he gets up and prays, he prays in virtue.'\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، قَالَ‏:‏ حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ حَجَّاجٍ الصَّوَّافِ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ قَالَ‏:‏ إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ أَوْ أَوَى إِلَى فِرَاشِهِ ابْتَدَرَهُ مَلَكٌ وَشَيْطَانٌ، فَقَالَ الْمَلَكُ‏:‏ اخْتِمْ بِخَيْرٍ، وَقَالَ الشَّيْطَانُ‏:‏ اخْتِمْ بِشَرٍّ، فَإِنْ حَمِدَ اللَّهَ وَذَكَرَهُ أَطْرَدَهُ، وَبَاتَ يَكْلَؤُهُ، فَإِذَا اسْتَيْقَظَ ابْتَدَرَهُ مَلَكٌ وَشَيْطَانٌ فَقَالاَ مِثْلَهُ، فَإِنْ ذَكَرَ اللَّهَ وَقَالَ‏:‏ الْحَمْدُ لِلَّهِ الَّذِي رَدَّ إِلَيَّ نَفْسِي بَعْدَ مَوْتِهَا وَلَمْ يُمِتْهَا فِي مَنَامِهَا، الْحَمْدُ لِلَّهِ الَّذِي ‏{‏يُمْسِكُ السَّمَوَاتِ وَالأَرْضَ أَنْ تَزُولاَ، وَلَئِنْ زَالَتَا إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِنْ بَعْدِهِ إِنَّهُ كَانَ حَلِيمًا غَفُورًا‏}‏، الْحَمْدُ لِلَّهِ الَّذِي ‏{‏يُمْسِكُ السَّمَاءَ أَنْ تَقَعَ عَلَى الأَرْضِ إِلاَّ بِإِذْنِهِ‏}‏ إِلَى ‏{‏لَرَءُوفٌ رَحِيمٌ‏}‏، فَإِنْ مَاتَ مَاتَ شَهِيدًا، وَإِنْ قَامَ فَصَلَّى صَلَّى فِي فَضَائِلَ‏.‏","v":[]}]};